    let badgeNow=Date.now(),badgeCount=all.filter(a=>{let d=firebaseToDate(a.dueAt);return !a.submission&&d&&d.getTime()<=badgeNow+24*3600e3}).length;firebaseSetNotificationBadge(badgeCount);
