    let a=aSnap.data()||{},d=sSnap.exists?sSnap.data():(iSnap.data()||{}),idx=iSnap.exists?iSnap.data():{},n=Math.max(v27AttemptNumber(d),v27AttemptNumber(idx)),oldMax=v27MaxAttempts(a),newMax=Math.max(oldMax,n+1);
