/* ===== assets/js/student-ux-v28.js ===== */
/* Math12 Hub  — Student Learning UX
   Personal goal, next-best-action queue, dynamic 7-day plan, mistake notebook.
    self-study focus: recommendations use only questions/codes that exist in the current learner bank; online-class assignments are excluded. */
const V28_DEFAULT_PLAN={targetScore:8,dailyMinutes:35,weeklyDays:5,updatedAt:''};
let v28ActionCache=[];
function v383PracticeBank(){return window.V383PracticeBank?.effectiveBank?.()||window.V3822PracticeBank?.effectiveBank?.({approvedOnly:false})||(state.questionBank||[])}
function v383BankIds(){return new Set(v383PracticeBank().map(q=>q?.id).filter(Boolean))}
