/* ===== assets/js/exam-pro-v30.js ===== */
/* =========================  • EXAM ENGINE PRO =========================
   - Multiple deterministic exam codes without duplicating the question bank
   - Controlled question / MCQ option shuffling
   - Assignment reveal policy
   - Cloud draft autosave for secure assignments
   - Variant-aware grading while keeping Secure Exam  + Low Reads 
*/
const V30_EXAM_SCHEMA=30;
const V30_VARIANT_CODES=['A','B','C','D','E','F','G','H'];
let v30CloudDraftTimer=null,v30CloudDraftLastWrite=0,v30CloudDraftHash='';

function v30Int(v,min=0,max=999){return Math.min(max,Math.max(min,parseInt(v,10)||0))}
function v30PolicyDefaults(){return {variantCount:1,shuffleQuestions:true,shuffleOptions:true,revealPolicy:'after_due',preserveSections:true}}
function v30NormalizePolicy(p={}){let d=v30PolicyDefaults(),r={...d,...(p||{})};r.variantCount=v30Int(r.variantCount,1,8);r.shuffleQuestions=r.shuffleQuestions!==false;r.shuffleOptions=r.shuffleOptions!==false;r.preserveSections=r.preserveSections!==false;r.revealPolicy=['never','after_due','after_grade'].includes(r.revealPolicy)?r.revealPolicy:'after_due';return r}
function v30PolicyFromBuilder(){return v30NormalizePolicy({variantCount:document.getElementById('ebV30VariantCount')?.value||1,shuffleQuestions:!!document.getElementById('ebV30ShuffleQuestions')?.checked,shuffleOptions:!!document.getElementById('ebV30ShuffleOptions')?.checked,preserveSections:!!document.getElementById('ebV30PreserveSections')?.checked,revealPolicy:document.getElementById('ebV30RevealPolicy')?.value||'after_due'})}
function v30RefreshBuilderPolicy(){if(typeof examBuilderDraft!=='undefined'&&examBuilderDraft){examBuilderDraft.v30Policy=v30PolicyFromBuilder();examBuilderDraft.variantCount=examBuilderDraft.v30Policy.variantCount;examBuilderDraft.schemaVersion=30}if(typeof updateExamBuilderSummary==='function')updateExamBuilderSummary();if(typeof renderExamBuilderPreview==='function'&&typeof examBuilderDraft!=='undefined'&&examBuilderDraft)renderExamBuilderPreview()}
function v30PolicyFromExam(e={}){let hasV30=!!e.v30Policy||e.v30ExamEngine===true||e.schemaVersion===30||e.variantCount!=null||e.shuffleQuestions!=null||e.shuffleOptions!=null||e.revealPolicy!=null;if(!hasV30)return {variantCount:1,shuffleQuestions:false,shuffleOptions:false,preserveSections:true,revealPolicy:'never'};return v30NormalizePolicy(e.v30Policy||{variantCount:e.variantCount,shuffleQuestions:e.shuffleQuestions,shuffleOptions:e.shuffleOptions,preserveSections:e.preserveSections,revealPolicy:e.revealPolicy})}
function v30VariantCode(i=0){return V30_VARIANT_CODES[v30Int(i,0,7)]||String(i+1)}
function v30Hash(text=''){return typeof examSeedFromText==='function'?examSeedFromText(String(text)):String(text).split('').reduce((h,c)=>((h*31+c.charCodeAt(0))>>>0),2166136261)}
function v30VariantIndex(a={},uid='',attemptNumber=1){let p=v30NormalizePolicy(a.v30Policy||a),n=p.variantCount;if(n<=1)return 0;return (v30Hash(`${uid}|${a.id||a.assignmentId||a.sourceExamId||''}`)+Math.max(0,(Number(attemptNumber)||1)-1))%n}
function v30Permutation(n,seed){return examShuffle(Array.from({length:n},(_,i)=>i),seed)}
function v30ShuffleQuestionOptions(q,seed){let x=firebaseSafeClone?firebaseSafeClone(q):JSON.parse(JSON.stringify(q));if(x.type!=='mcq'||!Array.isArray(x.options)||x.options.length<2)return x;let perm=v30Permutation(x.options.length,seed),old=x.options.slice(),oldAnswer=Number(x.answer);x.options=perm.map(i=>old[i]);if(Number.isInteger(oldAnswer)&&oldAnswer>=0&&oldAnswer<old.length)x.answer=perm.indexOf(oldAnswer);x.v30OptionOrder=perm;return x}
function v30ApplyVariant(questions=[],policy={},variantIndex=0,context='exam'){
  let p=v30NormalizePolicy(policy),seed=v30Hash(`${context}|variant:${variantIndex}|v30`),qs=(questions||[]).map((q,i)=>p.shuffleOptions?v30ShuffleQuestionOptions(q,v30Hash(`${seed}|${q.id||i}|options`)):(firebaseSafeClone?firebaseSafeClone(q):JSON.parse(JSON.stringify(q))));
  if(p.shuffleQuestions){
    const hasSections=p.preserveSections&&qs.some(q=>q.section);
    if(hasSections){let order=['I','II','III'],seen=new Set(order),groups=[];order.forEach(s=>{let g=qs.filter(q=>q.section===s);if(g.length)groups.push(examShuffle(g,v30Hash(`${seed}|section:${s}`)))});let rest=qs.filter(q=>!seen.has(q.section));if(rest.length)groups.push(examShuffle(rest,v30Hash(`${seed}|section:rest`)));qs=groups.flat()}
    else qs=examShuffle(qs,seed);
  }
  return qs.map((q,i)=>({...q,v30DisplayNo:i+1}));
}
function v30VariantMeta(policy,index){let p=v30NormalizePolicy(policy);return {variantIndex:index,variantCode:v30VariantCode(index),variantCount:p.variantCount,shuffleQuestions:p.shuffleQuestions,shuffleOptions:p.shuffleOptions,preserveSections:p.preserveSections}}
function v30RevealLabel(v){return ({never:'Không công bố đáp án',after_due:'Sau khi hết hạn',after_grade:'Sau khi giáo viên chấm'})[v]||'Sau khi hết hạn'}

/* ---------- Exam builder ---------- */
const v30OldGenerateExamBuilderDraft=generateExamBuilderDraft;
