/* ===== assets/js/analytics-pro-v31.js ===== */
/* =========================  • ANALYTICS & COMPETENCY PRO =========================
   Verified Secure Exam competency is aggregated into studentStatsV19 so the teacher
   dashboard can render Chapter → Lesson → Knowledge Code → NB/TH/VD without loading
   full submissions. Practice/self-reported progress remains clearly separated.
   ================================================================================ */
const V31_ANALYTICS_SCHEMA=31;
let v31LastClassData=null;

function v31SafeKey(v=''){return String(v||'').replace(/[^A-Za-z0-9_-]/g,c=>'_'+c.charCodeAt(0).toString(16)+'_')||'_'}
function v31Clamp01(v){v=Number(v);return Number.isFinite(v)?Math.max(0,Math.min(1,v)):0}
function v31KnowledgeMeta(code=''){return (typeof allKnowledgeCodes==='function'?allKnowledgeCodes():[]).find(x=>x.code===code)||null}
function v31Level(v=''){v=String(v||'').toUpperCase();return ['NB','TH','VD'].includes(v)?v:'OTHER'}
function v31ResolvedResult(r={}){let meta=v31KnowledgeMeta(r.knowledgeCode||'')||{},code=r.knowledgeCode||'',lessonId=r.lessonId||meta.lessonId||'',chapterId=Number(r.chapterId||meta.chapterId)||0,level=v31Level(r.level||meta.level||'');return {...r,code,lessonId,chapterId,level,title:meta.title||code,credit:v31Clamp01(r.credit),correct:!!r.correct}}
function v31CompetencyNumeric(rows=[]){return (rows||[]).map(v31ResolvedResult).filter(r=>r.code)}
function v31AddBucket(map,key,meta,r,sign=1){if(!key)return;let x=map[key]||(map[key]={...meta,attempts:0,credit:0,correct:0});x.attempts+=sign;x.credit+=sign*r.credit;x.correct+=sign*(r.correct?1:0)}
function v31AggregateResults(rows=[]){
  const out={schemaVersion:31,totalAttempts:0,totalCredit:0,totalCorrect:0,codes:{},lessons:{},chapters:{},levels:{}};
  v31CompetencyNumeric(rows).forEach(r=>{out.totalAttempts++;out.totalCredit+=r.credit;out.totalCorrect+=r.correct?1:0;v31AddBucket(out.codes,v31SafeKey(r.code),{code:r.code,title:r.title,lessonId:r.lessonId,chapterId:r.chapterId,level:r.level},r);v31AddBucket(out.lessons,v31SafeKey(r.lessonId),{lessonId:r.lessonId,chapterId:r.chapterId},r);v31AddBucket(out.chapters,String(r.chapterId),{chapterId:r.chapterId},r);v31AddBucket(out.levels,r.level,{level:r.level},r)});return out
}
function v31StudentStatsDeltaPayload(rows=[],sign=1){
  if(!firebase?.firestore?.FieldValue)return {};
  const inc=firebase.firestore.FieldValue.increment,agg=v31AggregateResults(rows),obj={schemaVersion:31,totalAttempts:inc(sign*agg.totalAttempts),totalCredit:inc(sign*agg.totalCredit),totalCorrect:inc(sign*agg.totalCorrect),updatedAt:firebaseServerTimestamp(),codes:{},lessons:{},chapters:{},levels:{}};
  for(const [k,x] of Object.entries(agg.codes))obj.codes[k]={code:x.code,title:x.title||x.code,lessonId:x.lessonId||'',chapterId:Number(x.chapterId)||0,level:x.level||'',attempts:inc(sign*x.attempts),credit:inc(sign*x.credit),correct:inc(sign*x.correct)};
  for(const [k,x] of Object.entries(agg.lessons))obj.lessons[k]={lessonId:x.lessonId||'',chapterId:Number(x.chapterId)||0,attempts:inc(sign*x.attempts),credit:inc(sign*x.credit),correct:inc(sign*x.correct)};
  for(const [k,x] of Object.entries(agg.chapters))obj.chapters[k]={chapterId:Number(x.chapterId)||0,attempts:inc(sign*x.attempts),credit:inc(sign*x.credit),correct:inc(sign*x.correct)};
  for(const [k,x] of Object.entries(agg.levels))obj.levels[k]={level:x.level||k,attempts:inc(sign*x.attempts),credit:inc(sign*x.credit),correct:inc(sign*x.correct)};
  return {verifiedCompetencyV31:obj,verifiedCompetencySchemaVersion:31}
}
function v31NormalizeStoredCompetency(x={}){let out={schemaVersion:Number(x.schemaVersion)||31,totalAttempts:Math.max(0,Number(x.totalAttempts)||0),totalCredit:Math.max(0,Number(x.totalCredit)||0),totalCorrect:Math.max(0,Number(x.totalCorrect)||0),codes:{},lessons:{},chapters:{},levels:{}};for(const part of ['codes','lessons','chapters','levels'])for(const [k,v] of Object.entries(x?.[part]||{})){let attempts=Math.max(0,Number(v?.attempts)||0),credit=Math.max(0,Number(v?.credit)||0),correct=Math.max(0,Number(v?.correct)||0);if(attempts>0)out[part][k]={...v,attempts,credit,correct,accuracy:credit/attempts}}out.accuracy=out.totalAttempts?out.totalCredit/out.totalAttempts:null;return out}
function v31MergeStoredCompetencies(list=[]){let out={schemaVersion:31,totalAttempts:0,totalCredit:0,totalCorrect:0,codes:{},lessons:{},chapters:{},levels:{}};for(const raw of list){let c=v31NormalizeStoredCompetency(raw||{});out.totalAttempts+=c.totalAttempts;out.totalCredit+=c.totalCredit;out.totalCorrect+=c.totalCorrect;for(const part of ['codes','lessons','chapters','levels'])for(const [k,x] of Object.entries(c[part]||{})){let y=out[part][k]||(out[part][k]={...x,attempts:0,credit:0,correct:0,students:0});y.attempts+=x.attempts;y.credit+=x.credit;y.correct+=x.correct;y.students+=1;y.accuracy=y.attempts?y.credit/y.attempts:null}}out.accuracy=out.totalAttempts?out.totalCredit/out.totalAttempts:null;return out}
function v31State(acc,attempts){if(!attempts||attempts<2)return 'new';if(acc<.6)return 'weak';if(acc<.8)return 'reinforce';return 'strong'}
function v31Pct(v){return v==null?'—':Math.round(Number(v)*100)+'%'}

/* ---------- Aggregate official Secure Exam results once ---------- */
async function v31AggregateOfficialRows(classId,assignmentId,rows=[]){
  let pending=(rows||[]).filter(x=>x&&x.score!=null&&Array.isArray(x.questionResults)&&x.questionResults.length&&!x.competencyV31Aggregated);if(!pending.length)return 0;
  for(let i=0;i<pending.length;i+=80){let b=firebaseDb.batch();pending.slice(i,i+80).forEach(x=>{let uid=x.uid||x.id||'';if(!uid)return;let stats={uid,classId,name:x.name||'',email:x.email||'',schemaVersion:31,updatedAt:firebaseServerTimestamp(),...v31StudentStatsDeltaPayload(x.questionResults,1)};b.set(firebaseStudentStatsRef(classId).doc(uid),stats,{merge:true});b.set(firebaseAssignmentsRef(classId).doc(assignmentId).collection('submissions').doc(uid),{competencyV31Aggregated:true,competencyV31SchemaVersion:31,competencyV31AggregatedAt:firebaseServerTimestamp()},{merge:true});x.competencyV31Aggregated=true});await b.commit()}
  firebaseV19InvalidateClass(classId);return pending.length
}
const v31OldGradePending=typeof firebaseGradePendingSubmissionDocs==='function'?firebaseGradePendingSubmissionDocs:null;
if(v31OldGradePending)firebaseGradePendingSubmissionDocs=async function(classId,assignmentId,a,sDocs){let rows=await v31OldGradePending(classId,assignmentId,a,sDocs);try{await v31AggregateOfficialRows(classId,assignmentId,rows)}catch(err){console.warn(' competency aggregate',err)}return rows};

/*  retry removes the previous official competency contribution before the next attempt. */
firebaseResetSubmission=async function(classId,assignmentId,uid){
  if(!requireTeacher('Cấp thêm lượt làm'))return;
  try{let aRef=firebaseAssignmentsRef(classId).doc(assignmentId),subRef=aRef.collection('submissions').doc(uid),idxRef=firebaseSubmissionIndexRef(classId).doc(firebaseSubmissionIndexId(assignmentId,uid)),[aSnap,sSnap,iSnap]=await Promise.all([aRef.get(),subRef.get(),idxRef.get()]);if(!aSnap.exists)return alert('Bài giao không còn tồn tại.');if(!sSnap.exists&&!iSnap.exists)return alert('Học sinh chưa có lượt nộp để cấp lại.');let a=aSnap.data()||{},d=sSnap.exists?sSnap.data():(iSnap.data()||{}),idx=iSnap.exists?iSnap.data():{},n=Math.max(v27AttemptNumber(d),v27AttemptNumber(idx)),oldMax=v27MaxAttempts(a),newMax=Math.max(oldMax,n+1);if(n>=5&&oldMax>=5)return alert(' đang giới hạn tối đa 5 lượt cho một bài. Học sinh này đã dùng đủ 5 lượt.');newMax=Math.min(5,newMax);if(!confirm(`Cấp thêm lượt ${n+1}/${newMax} cho ${d.name||d.email||uid}? Điểm và năng lực xác minh của lượt hiện tại sẽ được gỡ khỏi thống kê chính thức; lịch sử lượt vẫn được giữ.`))return;if(typeof v26StoreSubmissionRecoveryBundle==='function')await v26StoreSubmissionRecoveryBundle(classId,assignmentId,uid);let retryIndex={uid,name:d.name||idx.name||'',email:d.email||idx.email||'',classId,assignmentId,assignmentTitle:d.assignmentTitle||idx.assignmentTitle||a.title||'',attemptId:d.attemptId||idx.attemptId||'',attemptNumber:n,answered:Number(d.answered??idx.answered)||0,total:Number(d.total??idx.total)||Number(a.questionCount)||0,durationMs:Number(d.durationMs??idx.durationMs)||0,violations:Number(d.violations??idx.violations)||0,status:'retry',secureSchemaVersion:FIREBASE_SECURE_SCHEMA,indexSchemaVersion:19,submittedAt:d.submittedAt||idx.submittedAt||firebaseServerTimestamp()},b=firebaseDb.batch();if(sSnap.exists)b.delete(subRef);b.set(idxRef,retryIndex,{merge:false});if(newMax!==oldMax)b.set(aRef,{maxAttempts:newMax,updatedAt:firebaseServerTimestamp()},{merge:true});if(d.score!=null){let score=Number(d.score)||0,stats={gradedCount:firebase.firestore.FieldValue.increment(-1),scoreSum:firebase.firestore.FieldValue.increment(-score),gradedAssignmentIds:firebase.firestore.FieldValue.arrayRemove(assignmentId),updatedAt:firebaseServerTimestamp()};if(d.competencyV31Aggregated&&Array.isArray(d.questionResults))Object.assign(stats,v31StudentStatsDeltaPayload(d.questionResults,-1));b.set(aRef,{gradedCount:firebase.firestore.FieldValue.increment(-1),scoreSum:firebase.firestore.FieldValue.increment(-score),updatedAt:firebaseServerTimestamp()},{merge:true});b.set(firebaseStudentStatsRef(classId).doc(uid),stats,{merge:true})}await b.commit();await firebaseAuditLog('assignment.retry.grant.v31',{classId,assignmentId,uid,previousAttempt:n,maxAttempts:newMax});firebaseV19InvalidateClass(classId);closeModal();await firebaseShowAssignmentResults(classId,assignmentId)}catch(err){alert(firebaseErrorText(err))}
};

/* Rare destructive path, but keep official competency exact when an assignment is purged. */
firebasePurgeAssignment=async function(classId,assignmentId){
  if(!requireTeacher('Xóa vĩnh viễn bài giao'))return;let ref=firebaseAssignmentsRef(classId).doc(assignmentId);try{let aSnap=await ref.get();if(!aSnap.exists)return alert('Bài giao không còn tồn tại.');let a=aSnap.data()||{};if(a.status!=='trashed')return alert(' chỉ cho xóa vĩnh viễn bài đang ở Thùng rác.');let token=prompt(`Xóa vĩnh viễn “${a.title||'Bài giao'}” cùng lượt nộp?\n\nNhập XOA để xác nhận:`);if(String(token||'').trim().toUpperCase()!=='XOA')return;if(typeof v26StoreAssignmentRecoveryBundle==='function')await v26StoreAssignmentRecoveryBundle(classId,assignmentId);let [subs,idx,attempts,drafts]=await Promise.all([ref.collection('submissions').get(),firebaseSubmissionIndexRef(classId).where('assignmentId','==',assignmentId).get(),ref.collection('attemptHistoryV27').get(),ref.collection('draftsV30').get()]);for(let i=0;i<subs.docs.length;i+=90){let b=firebaseDb.batch();subs.docs.slice(i,i+90).forEach(d=>{let x=d.data()||{};b.delete(d.ref);if(x.score!=null){let score=Number(x.score)||0,stats={gradedCount:firebase.firestore.FieldValue.increment(-1),scoreSum:firebase.firestore.FieldValue.increment(-score),gradedAssignmentIds:firebase.firestore.FieldValue.arrayRemove(assignmentId),updatedAt:firebaseServerTimestamp()};if(x.competencyV31Aggregated&&Array.isArray(x.questionResults))Object.assign(stats,v31StudentStatsDeltaPayload(x.questionResults,-1));b.set(firebaseStudentStatsRef(classId).doc(d.id),stats,{merge:true})}});await b.commit()}for(const snap of [idx,attempts,drafts])for(let i=0;i<snap.docs.length;i+=350){let b=firebaseDb.batch();snap.docs.slice(i,i+350).forEach(d=>b.delete(d.ref));await b.commit()}let b=firebaseDb.batch();b.delete(ref);b.delete(firebaseAnswerKeysRef(classId).doc(assignmentId));await b.commit();await firebaseAuditLog('assignment.purge.v31',{classId,assignmentId,title:a.title||'',submissionCount:subs.size});firebaseV19InvalidateClass(classId);closeModal();await firebaseRefreshAssignments();alert('Đã xóa vĩnh viễn.  đã đồng thời gỡ phần năng lực xác minh của bài khỏi thống kê chính thức.')}catch(err){alert(firebaseErrorText(err))}
};

async function v31BackfillClassCompetency(classId){
  if(!requireTeacher('Chuẩn hóa năng lực xác minh '))return;if(!classId)return alert('Hãy chọn lớp.');if(!confirm(' sẽ đọc các submission đã chấm của lớp để bổ sung năng lực xác minh cho dữ liệu  trở về trước. Đây là thao tác một lần và có phát sinh Reads. Tiếp tục?'))return;
  let scanned=0,added=0;try{let assignments=await firebaseV19LoadAssignments(classId,true);for(const row of assignments){let aid=row.id,s=await firebaseAssignmentsRef(classId).doc(aid).collection('submissions').get();scanned+=s.size;let rows=s.docs.map(d=>({id:d.id,...d.data()})).filter(x=>x.score!=null&&Array.isArray(x.questionResults)&&x.questionResults.length&&!x.competencyV31Aggregated);if(rows.length)added+=await v31AggregateOfficialRows(classId,aid,rows)}await firebaseDb.collection('classes').doc(classId).set({competencyV31Ready:true,competencyV31BackfillAt:firebaseServerTimestamp()},{merge:true});await firebaseAuditLog('analytics.competency.backfill.v31',{classId,scanned,added});firebaseTeacherDashboardCache=null;await firebaseRefreshTeacherDashboard(true);alert(`Đã chuẩn hóa : quét ${scanned} bài nộp, bổ sung ${added} lượt chấm vào bản đồ năng lực xác minh.`)}catch(err){alert(firebaseErrorText(err))}
}

/* ---------- Low-read class intelligence: reuse studentStatsV19 ---------- */
