if(v31OldBuildTeacherData)firebaseBuildTeacherDashboardData=function(args={}){let c=v31OldBuildTeacherData(args),sm=new Map((args.studentStats||[]).map(x=>[x.id,x.data||x]));c.students.forEach(s=>{let st=sm.get(s.uid)||{};s.verifiedCompetencyV31=v31NormalizeStoredCompetency(st.verifiedCompetencyV31||{})});c.verifiedCompetencyV31=v31MergeStoredCompetencies(c.students.map(s=>s.verifiedCompetencyV31));c.verifiedCompetencyEvidence=c.verifiedCompetencyV31.totalAttempts;c.verifiedCompetencyAccuracy=c.verifiedCompetencyV31.accuracy;c.verifiedCompetencyCoverage=Object.values(c.verifiedCompetencyV31.codes||{}).filter(x=>x.attempts>=2).length;return c};

function v31CodeRows(c){let meta=typeof allKnowledgeCodes==='function'?allKnowledgeCodes():[],map=new Map(Object.values(c?.verifiedCompetencyV31?.codes||{}).map(x=>[x.code,x]));return meta.map((m,i)=>{let x=map.get(m.code)||{},attempts=Number(x.attempts)||0,credit=Number(x.credit)||0,accuracy=attempts?credit/attempts:null;return {...m,order:i,attempts,credit,accuracy,correct:Number(x.correct)||0,students:Number(x.students)||0,state:v31State(accuracy,attempts)}})}
function v31ChapterRows(c){let comp=c?.verifiedCompetencyV31||{},map=comp.chapters||{};return chapters.map(ch=>{let x=map[String(ch.id)]||{},attempts=Number(x.attempts)||0,accuracy=attempts?Number(x.credit||0)/attempts:null;return {id:ch.id,title:ch.title,attempts,accuracy,state:v31State(accuracy,attempts)}})}
function v31LessonRows(c,chapterId=0){let comp=c?.verifiedCompetencyV31||{},map=comp.lessons||{};return chapters.filter(ch=>!chapterId||ch.id===chapterId).flatMap(ch=>ch.lessons.map(l=>{let x=Object.values(map).find(v=>v.lessonId===l.id)||{},attempts=Number(x.attempts)||0,accuracy=attempts?Number(x.credit||0)/attempts:null;return {id:l.id,title:l.common,chapterId:ch.id,attempts,accuracy,state:v31State(accuracy,attempts)}}))}
function v31LevelRows(c){let map=c?.verifiedCompetencyV31?.levels||{};return ['NB','TH','VD'].map(level=>{let x=map[level]||{},attempts=Number(x.attempts)||0,accuracy=attempts?Number(x.credit||0)/attempts:null;return {level,attempts,accuracy,state:v31State(accuracy,attempts)}})}
