function v31HistorySummary(rows=[]){let out={total:0,credit:0,chapters:{},levels:{NB:{n:0,c:0},TH:{n:0,c:0},VD:{n:0,c:0}}};(rows||[]).forEach(h=>{let r=v31ResolvedResult(h);if(!r.code)return;out.total++;out.credit+=r.credit;let ch=out.chapters[r.chapterId]||(out.chapters[r.chapterId]={n:0,c:0});ch.n++;ch.c+=r.credit;if(out.levels[r.level]){out.levels[r.level].n++;out.levels[r.level].c+=r.credit}});out.accuracy=out.total?out.credit/out.total:null;return out}
function v31RenderStudentTrust(){let box=document.getElementById('v31StudentTrust');if(!box||typeof analyticsHistory!=='function')return;let h=analyticsHistory(),verified=h.filter(x=>String(x.mode||'').startsWith('assignment')),practice=h.filter(x=>!String(x.mode||'').startsWith('assignment')),v=v31HistorySummary(verified),p=v31HistorySummary(practice),levels=['NB','TH','VD'].map(k=>{let x=v.levels[k];return `<span><b>${k}</b> ${x.n?v31Pct(x.c/x.n):'—'} <small>(${x.n})</small></span>`}).join('');box.innerHTML=`<div class="v31-source-card verified"><div><b>✓ Secure Exam đã xác minh</b><strong>${v31Pct(v.accuracy)}</strong><small>${v.total} kết quả câu</small></div><div class="v31-source-levels">${levels}</div></div><div class="v31-source-card practice"><div><b>◎ Tự luyện trên thiết bị</b><strong>${v31Pct(p.accuracy)}</strong><small>${p.total} kết quả câu</small></div><div class="v31-source-note">Dùng để cá nhân hóa luyện tập; không thay điểm bài giáo viên chấm.</div></div>`}
