function builderFields(type,s){
  if(type==='cubic')return `<div class="v373-coeff-grid">${['a','b','c','d'].map(k=>`<label><span>${k}</span><input id="v373_${k}" type="number" step="any" value="${escHtml(fmt(s[k]))}"></label>`).join('')}</div><div class="math-help">$y=ax^3+bx^2+cx+d$, với $a\\ne0$.</div>`;
  if(type==='rational11')return `<div class="v373-coeff-grid">${['a','b','c','d'].map(k=>`<label><span>${k}</span><input id="v373_${k}" type="number" step="any" value="${escHtml(fmt(s[k]))}"></label>`).join('')}</div><div class="math-help">$y=\\dfrac{ax+b}{cx+d}$, với $c\\ne0$.</div>`;
  return `<div class="v373-coeff-grid">${['a','b','c','d','e'].map(k=>`<label><span>${k}</span><input id="v373_${k}" type="number" step="any" value="${escHtml(fmt(s[k]))}"></label>`).join('')}</div><div class="math-help">$y=\\dfrac{ax^2+bx+c}{dx+e}$, với $d\\ne0$.</div>`
}
function readBuilder(){const type=document.getElementById('v373Type')?.value||'cubic',preset=normalizePreset(document.getElementById('v373Preset')?.value||'exam'),s=applyPresetToSpec(defaultSpec(type),preset);['a','b','c','d','e'].forEach(k=>{const el=document.getElementById('v373_'+k);if(el)s[k]=num(el.value,s[k]??0)});s.preset=preset;s.showGrid=!!document.getElementById('v373Grid')?.checked;s.examStyle=!!document.getElementById('v373ExamStyle')?.checked;s.smartLabels=document.getElementById('v373SmartLabels')?.checked!==false;s.showAsymptotes=!!document.getElementById('v373Asym')?.checked;s.showExtrema=!!document.getElementById('v373Extrema')?.checked;s.showGuides=!!document.getElementById('v373Guides')?.checked;s.showPointLabels=!!document.getElementById('v373Labels')?.checked;s.showIntercepts=!!document.getElementById('v373Intercepts')?.checked;s.showInflection=!!document.getElementById('v373Inflection')?.checked;[['xmin','v373XMin'],['xmax','v373XMax'],['ymin','v373YMin'],['ymax','v373YMax']].forEach(([k,id])=>{const el=document.getElementById(id),v=el?.value?.trim();if(v)s[k]=num(v,undefined)});return s}
function setVisualControls(s={}){const pairs={v373ExamStyle:s.examStyle!==false,v373Grid:s.showGrid!==false,v373SmartLabels:s.smartLabels!==false,v373Asym:s.showAsymptotes!==false,v373Extrema:s.showExtrema!==false,v373Guides:s.showGuides!==false,v373Labels:!!s.showPointLabels,v373Intercepts:!!s.showIntercepts,v373Inflection:!!s.showInflection};Object.entries(pairs).forEach(([id,v])=>{const el=document.getElementById(id);if(el)el.checked=!!v})}
function updatePresetHelp(){const el=document.getElementById('v373PresetHelp'),name=normalizePreset(document.getElementById('v373Preset')?.value||'exam'),type=document.getElementById('v373Type')?.value||'cubic';if(!el)return;const msg=name==='exam'?'Hình sạch theo phong cách đề thi: không lưới, chỉ hiện mốc cần thiết, nhãn tự tránh đồ thị.':name==='analyze'?'Hiện nhiều đặc trưng để khảo sát: cực trị, giao trục, tọa độ điểm và điểm uốn (hàm bậc ba).':name==='asymptote'?(type==='cubic'?'Preset này phù hợp hơn với hàm phân thức; hàm bậc ba sẽ hiển thị tối giản.':'Tập trung vào tiệm cận và giao trục, phù hợp câu nhận dạng đồ thị.'): 'Giữ nguyên các thiết lập nâng cao do giáo viên tự chọn.';el.textContent=msg}
function applyBuilderPreset(){const name=normalizePreset(document.getElementById('v373Preset')?.value||'exam'),type=document.getElementById('v373Type')?.value||'cubic';if(name!=='custom')setVisualControls(applyPresetToSpec(defaultSpec(type),name));updatePresetHelp();refreshBuilder(false)}
