  const cases=[
    [1.12,'graph-oxy','', 'graph'],[2.4,'tikz','', 'wide'],[.55,'tikz','', 'tall'],[1.2,'tikz','', 'standard'],[3,'tikz','tkztab','table']
  ];
  const mapped=cases.map(c=>layoutFor(c[0],c[1],c[2]).preset),ok=cases.every((c,i)=>mapped[i]===c[3]);
