function regression(){const sample={id:'V375-REG',reviewStatus:'approved',figureMode:'tikz',figureLatex:'\\begin{tikzpicture}[scale=.88,>=stealth]\\draw[->](-3.2,0)--(3.2,0) node[below]{$x$};\\draw[->](0,-2.8)--(0,2.8) node[right]{$y$};\\draw[dashed](-1,-2.8)--(-1,2.8);\\draw[dashed](-3,-1)--(3,-1);\\draw[thick,samples=100,domain=-3:-1.12] plot(\\x,{-\\x/(\\x+1)});\\draw[thick,samples=100,domain=-.88:3] plot(\\x,{-\\x/(\\x+1)});\\end{tikzpicture}'};let n={ok:false},r={pass:false};try{n=fe()?.smartNativeSvg?.(sample.figureLatex)||{ok:false};r=qc(sample)}catch(_){}return {ok:!!(n.ok&&r.pass&&sourceHash(sample)&&typeof audit==='function'&&typeof seal==='function'),width:n.width||0,height:n.height||0}}
function patchProductionChecks(){if(typeof window.v35RunRegressionChecks!=='function')return;const base=window.v35RunRegressionChecks;window.v35RunRegressionChecks=function(opts={}){const res=base(opts);try{const rr=regression(),exists=res?.checks?.some(x=>x.name==='Figure Production Gate ');if(res?.checks&&!exists){res.checks.push({name:'Figure Production Gate ',ok:rr.ok,detail:rr.ok?`Release signature • Safe Repair • snapshot invalidation • sample ${rr.width}×${rr.height}`:'Figure Production regression chưa đạt',level:rr.ok?'pass':'fail'});const a=audit();const level=a.fatalApproved?'fail':a.approvedUnverified?'warn':'pass';res.checks.push({name:'Ngân hàng hình Production ',ok:level==='pass',detail:a.fatalApproved?`${a.fatalApproved} hình Approved có lỗi chặn`:a.approvedUnverified?`${a.approvedUnverified} hình Approved chưa xác minh trực quan`:`${a.approvedFigures} hình Approved đã đạt Verified Production`,level});res.pass=res.checks.filter(x=>x.level==='pass').length;res.warn=res.checks.filter(x=>x.level==='warn').length;res.fail=res.checks.filter(x=>x.level==='fail').length;if(opts.render!==false)window.v35RenderProductionCenter?.()}}catch(_){}return res}}
patchProductionChecks();
window.v375OpenProductionCenter=open;window.v375RefreshProductionCenter=refresh;window.v375PreviewFigure=preview;window.v375SafeRepairFigures=safeRepair;window.v375SealProduction=seal;window.v375ExportProductionManifest=exportManifest;
window.V375FigureProduction={version:V,build:BUILD,classification,audit,signature,safeRepair,seal,exportManifest,regression};
