  function baseFullQuestions(){try{return typeof fullExamQuestions==='function'?fullExamQuestions():base.thptExamConfig?.().questions||[]}catch(_){return []}}
  function fillWithFallback(primary,fallback,n,section,part){let out=primary.map(q=>normalized(q,section,part)),ids=new Set(out.map(q=>q.id));for(const q of fallback){if(out.length>=n)break;if(!ids.has(q.id)){out.push(normalized(q,section,part));ids.add(q.id)}}return out.slice(0,n)}
  function readiness(){let p=bank().filter(eligible);return {total:p.length,mcq:p.filter(q=>q.type==='mcq').length,tf4:p.filter(q=>q.type==='tf4').length,short:p.filter(q=>q.type==='short').length,approved:p.filter(q=>q.reviewStatus==='approved').length}}
  function generateOfficial(seed=Date.now()){
    let fb=baseFullQuestions(),code=nowCode(seed),m=pick(approvedPool('mcq'),12,h(`${seed}|I`),['NB','TH','NB','TH','VD','NB','TH','VD']),t=pick(approvedPool('tf4'),4,h(`${seed}|II`),['NB','TH','VD','TH']),s=pick(approvedPool('short'),6,h(`${seed}|III`),['TH','VD','NB','VD','TH','VD']);
    let I=fillWithFallback(m,fb.filter(q=>q.section==='I'),12,'I','Phần I • Nhiều lựa chọn'),II=fillWithFallback(t,fb.filter(q=>q.section==='II'),4,'II','Phần II • Đúng/Sai'),III=fillWithFallback(s,fb.filter(q=>q.section==='III'),6,'III','Phần III • Trả lời ngắn'),questions=[...I,...II,...III];
    let src={bank:I.filter(q=>bank().some(b=>b.id===q.id)).length+II.filter(q=>bank().some(b=>b.id===q.id)).length+III.filter(q=>bank().some(b=>b.id===q.id)).length,fallback:0};src.fallback=questions.length-src.bank;
    return {id:`thpt-v376-${code}-${(Number(seed)>>>0).toString(36)}`,mode:'thpt',title:`Đề thi thử tốt nghiệp THPT • Mã ${code}`,subtitle:'22 câu • 90 phút • 3 dạng thức • Exam Pro',durationMinutes:90,questions,scoring:'thpt',attemptType:'THPT-v37.6',seed:Number(seed)||Date.now(),examCode:code,v376:true,v376Mode:'official',strictExam:true,sourceStats:src,rules:'Thi như thật. Phần I: 12 câu nhiều lựa chọn; Phần II: 4 câu Đúng/Sai; Phần III: 6 câu trả lời ngắn. Hệ thống tự lưu, theo dõi nhịp làm bài và cho kiểm tra toàn bộ câu trước khi nộp.'}
  }
  function generatePractice(size=15,profile='balanced',seed=Date.now()){
    size=int(size,6,30);let all=approvedPool(),levels=profile==='target8'?['TH','VD','VDC','TH','VD']:profile==='foundation'?['NB','NB','TH','NB','TH']:['NB','TH','VD','NB','TH'],qs=pick(all,size,h(`${seed}|practice|${profile}`),levels).map(q=>normalized(q,'P','Luyện đề'));
    return {id:`practice-v376-${profile}-${(Number(seed)>>>0).toString(36)}`,mode:'practice-exam',title:profile==='target8'?'Luyện đề mục tiêu 8+':'Luyện đề thông minh',subtitle:`${qs.length} câu từ ngân hàng • ${profile==='target8'?'ưu tiên TH/VD':'cân bằng mức độ'}`,durationMinutes:Math.max(20,Math.round(qs.length*2.4)),questions:qs,scoring:'normalized',attemptType:`practice-v37.6-${profile}`,seed:Number(seed)||Date.now(),v376:true,v376Mode:'practice',profile,rules:'Luyện theo nhịp đề thi: không hiện đáp án trong lúc làm, tự lưu liên tục, có đánh dấu câu và phân tích lỗi sau khi nộp.'}
  }
  function saveActive(c){try{localStorage.setItem(ACTIVE_KEY,JSON.stringify(c))}catch(_){}}
  function loadActive(){try{let c=JSON.parse(localStorage.getItem(ACTIVE_KEY)||'null');return c?.questions?.length?c:null}catch(_){return null}}
  function activeHasDraft(c=loadActive()){try{return !!(c&&typeof readExamDraft==='function'&&readExamDraft(c))}catch(_){return false}}
