  function loadTelemetry(c){try{return JSON.parse(localStorage.getItem(TELEMETRY_PREFIX+c.id)||'null')}catch(_){return null}}
  function saveTelemetry(){if(!window.examSession?.v376||!examSession.config?.id)return;let x=examSession.v376;try{localStorage.setItem(TELEMETRY_PREFIX+examSession.config.id,JSON.stringify({questionTimes:x.questionTimes,current:examSession.current,enteredAt:x.enteredAt,switches:x.switches||0,updatedAt:Date.now()}))}catch(_){}}
  function commitTime(){let x=window.examSession?.v376;if(!x||!examSession.startedAt||examSession.submitted)return;let now=Date.now(),delta=Math.max(0,Math.min(10*60*1000,now-(x.enteredAt||now))),i=examSession.current;x.questionTimes[i]=(Number(x.questionTimes[i])||0)+delta;x.enteredAt=now;saveTelemetry()}
  function initTelemetry(resume=false){if(!window.examSession)return;let old=resume?loadTelemetry(examSession.config):null,n=examSession.config.questions.length;examSession.v376={questionTimes:Array.isArray(old?.questionTimes)?old.questionTimes.slice(0,n):Array(n).fill(0),enteredAt:Date.now(),switches:Number(old?.switches)||0};while(examSession.v376.questionTimes.length<n)examSession.v376.questionTimes.push(0);saveTelemetry()}
  function sectionTimes(qs,times){let o={I:0,II:0,III:0,P:0};qs.forEach((q,i)=>o[q.section] = (o[q.section]||0)+(Number(times?.[i])||0));return o}
  function currentElapsed(){let x=examSession?.v376;if(!x)return 0;return (Number(x.questionTimes?.[examSession.current])||0)+Math.max(0,Date.now()-(x.enteredAt||Date.now()))}
  function pace(){if(!examSession?.startedAt)return {label:'—',cls:''};let elapsed=Date.now()-examSession.startedAt,total=examSession.config.durationMinutes*60000,done=(examSession.current+1)/Math.max(1,examSession.config.questions.length),target=total*done,diff=elapsed-target;if(Math.abs(diff)<90e3)return {label:'Đúng nhịp',cls:'good'};if(diff>0)return {label:`Chậm ${Math.ceil(diff/60000)}′`,cls:'warn'};return {label:`Nhanh ${Math.ceil(-diff/60000)}′`,cls:'good'}
  }
  function updateRibbon(){if(!examSession?.startedAt)return;let qs=examSession.config.questions,stats=qs.map((q,i)=>status(q,examSession.answers[i])),done=stats.filter(x=>x==='answered').length,partial=stats.filter(x=>x==='partial').length,pct=Math.round((done+.5*partial)*100/Math.max(1,qs.length)),bar=document.querySelector('.v376-progress-line span');if(bar)bar.style.width=pct+'%';let l=document.getElementById('v376ProgressLabel');if(l)l.textContent=`${done}/${qs.length} câu hoàn thành`;let qtime=document.getElementById('v376QuestionTime');if(qtime)qtime.textContent=`⏱ Câu này ${fmtMs(currentElapsed())}`;let p=pace(),pc=document.getElementById('v376Pace');if(pc){pc.textContent=p.label;pc.className=`v376-chip ${p.cls}`};let net=document.getElementById('v376Network');if(net){net.textContent=navigator.onLine?'● Online':'● Offline';net.className=`v376-chip ${navigator.onLine?'good':'offline'}`}}
  function decorateRunner(){let view=document.getElementById('examView');if(!view||!examSession?.startedAt)return;let top=view.querySelector('.exam-top');if(top&&!view.querySelector('.v376-exam-ribbon'))top.insertAdjacentHTML('afterend',`<div class="v376-exam-ribbon"><div class="v376-progress-wrap"><div class="v376-progress-line"><span style="width:0"></span></div><div class="v376-progress-label"><span id="v376ProgressLabel">0/${examSession.config.questions.length} câu hoàn thành</span><span>${text(examSession.config.examCode?`Mã ${examSession.config.examCode}`:'Exam Pro ')}</span></div></div><div class="v376-ribbon-chips"><span id="v376Pace" class="v376-chip">—</span><span id="v376Network" class="v376-chip good">● Online</span><button class="exam-btn" onclick="v376ToggleFocus()">Tập trung</button></div></div>`);let qh=view.querySelector('.exam-question-head>div');if(qh&&!document.getElementById('v376QuestionTime'))qh.insertAdjacentHTML('beforeend','<div id="v376QuestionTime" class="v376-qtime">⏱ Câu này 0:00</div>');updateRibbon()}
  function decorateNavigator(){let side=document.getElementById('examSide');if(!side||side.querySelector('.v376-side-tools'))return;side.insertAdjacentHTML('beforeend',`<div class="v376-side-tools"><button class="exam-btn" onclick="v376ToggleFocus()">◫ Chế độ tập trung</button><button class="exam-btn" onclick="toggleExamFullscreen()">⛶ Toàn màn hình</button><button class="exam-btn" onclick="v376ShowShortcuts()">⌨ Phím tắt</button><div class="v376-shortcuts">←/→ chuyển câu • A–D hoặc 1–4 chọn đáp án • F đánh dấu • Ctrl+Enter kiểm tra trước khi nộp.</div></div>`)}
