  function showShortcuts(){examToast?.('Phím tắt: ←/→ chuyển câu • A–D/1–4 chọn MCQ • F đánh dấu • Ctrl+Enter kiểm tra nộp bài.')}
  function submitReview(){if(!examSession)return;let old=document.getElementById('v376SubmitReview');old?.remove();let qs=examSession.config.questions,st=qs.map((q,i)=>status(q,examSession.answers[i])),done=st.filter(x=>x==='answered').length,partial=st.filter(x=>x==='partial').length,empty=st.filter(x=>x==='empty').length,flagged=examSession.flags.filter(Boolean).length;let div=document.createElement('div');div.id='v376SubmitReview';div.className='v376-submit-backdrop';div.innerHTML=`<div class="v376-submit-card"><h3>Kiểm tra trước khi nộp</h3><p>Hệ thống đã tự lưu bài. Hãy kiểm tra các câu chưa hoàn thành hoặc đã đánh dấu trước khi kết thúc lượt thi.</p><div class="v376-submit-grid"><div class="v376-submit-stat"><b>${done}</b><small>Hoàn thành</small></div><div class="v376-submit-stat"><b>${empty+partial}</b><small>Chưa hoàn tất</small></div><div class="v376-submit-stat"><b>${flagged}</b><small>Đánh dấu</small></div></div>${empty+partial?`<div class="v376-submit-warning">Còn <b>${empty+partial}</b> câu chưa hoàn tất. Thầy/cô/học sinh có thể quay lại kiểm tra trước khi nộp.</div>`:'<div class="v376-submit-warning" style="background:#edf8f1;border-color:#cce8d7;color:#276443">Tất cả câu đã được trả lời đầy đủ.</div>'}<div class="v376-submit-actions"><button class="exam-btn" onclick="v376CloseSubmitReview()">Quay lại làm bài</button>${empty+partial?'<button class="exam-btn" onclick="v376GoFirstIncomplete()">Tới câu chưa làm</button>':''}<button class="exam-btn primary" onclick="v376SubmitNow()">Nộp bài</button></div></div>`;document.getElementById('examApp')?.appendChild(div)}
  function closeSubmitReview(){document.getElementById('v376SubmitReview')?.remove()}
  function goFirstIncomplete(){let i=examSession.config.questions.findIndex((q,j)=>status(q,examSession.answers[j])!=='answered');closeSubmitReview();if(i>=0)goExamQuestion(i)}
  function submitNow(){closeSubmitReview();window.submitExam(false)}
  function keyboard(e){if(!examSession?.startedAt||examSession.submitted||!document.getElementById('examApp')?.classList.contains('show'))return;let tag=(e.target?.tagName||'').toLowerCase(),typing=tag==='input'||tag==='textarea';if(e.ctrlKey&&e.key==='Enter'){e.preventDefault();submitReview();return}if(typing)return;if(e.key==='ArrowRight'){e.preventDefault();moveExamQuestion(1);return}if(e.key==='ArrowLeft'){e.preventDefault();moveExamQuestion(-1);return}if(e.key.toLowerCase()==='f'){e.preventDefault();toggleExamFlag();return}let q=examSession.config.questions[examSession.current];if(q?.type==='mcq'){let map={a:0,b:1,c:2,d:3,'1':0,'2':1,'3':2,'4':3},v=map[e.key.toLowerCase()];if(v!=null&&v<(q.options||[]).length){e.preventDefault();setExamAnswer(v)}}}
  function analysisHTML(result,times=[]){let details=result.details||[],correct=details.filter(d=>d.ok).length,total=details.length,avg=times.length?times.reduce((a,b)=>a+(Number(b)||0),0)/Math.max(1,times.filter(x=>Number(x)>0).length):0,byLevel={},byCode={};details.forEach((d,i)=>{let lv=d.q.level||'—',code=d.q.knowledgeCode||d.q.formId||'Chưa gắn mã';byLevel[lv]??={n:0,ok:0};byLevel[lv].n++;byLevel[lv].ok+=d.ok?1:0;byCode[code]??={n:0,ok:0,title:d.q.knowledgeTitle||d.q.formName||''};byCode[code].n++;byCode[code].ok+=d.ok?1:0});let weak=Object.entries(byCode).map(([code,x])=>({code,...x,acc:x.ok/x.n})).sort((a,b)=>a.acc-b.acc||b.n-a.n).slice(0,5),levels=Object.entries(byLevel).map(([lv,x])=>`<div class="v376-skill-row"><div><b>${text(lv)}</b><small>${x.ok}/${x.n} câu đúng</small></div><b>${Math.round(100*x.ok/x.n)}%</b></div>`).join('')||'<small>Chưa đủ dữ liệu.</small>',weakHtml=weak.map(x=>`<div class="v376-skill-row"><div><b>${text(displayKnowledgeCode(x.code))}</b><small>${text(x.title||'Mã kiến thức cần củng cố')}</small></div><b>${Math.round(x.acc*100)}%</b></div>`).join('')||'<small>Không có mã yếu nổi bật.</small>';return `<div class="v376-result-analysis"><h3>Phân tích Exam Pro</h3><div class="v376-analysis-note">Không chỉ xem điểm: hệ thống tổng hợp độ chính xác, tốc độ và mã kiến thức để tạo lượt luyện bù ngay sau đề.</div><div class="v376-analysis-grid"><div class="v376-analysis-card"><b>${correct}/${total}</b><small>Câu đúng hoàn toàn</small></div><div class="v376-analysis-card"><b>${Math.round(100*correct/Math.max(1,total))}%</b><small>Độ chính xác</small></div><div class="v376-analysis-card"><b>${fmtMs(avg)}</b><small>TB mỗi câu có ghi thời gian</small></div><div class="v376-analysis-card"><b>${examSession?.config?.examCode||'—'}</b><small>Mã đề</small></div></div><div class="v376-breakdown"><div class="v376-breakdown-box"><h4>Theo mức độ</h4>${levels}</div><div class="v376-breakdown-box"><h4>Mã cần củng cố</h4>${weakHtml}</div></div><div class="v376-result-actions"><button class="exam-btn primary" onclick="v376RetryWrong()">↻ Luyện lại câu sai</button><button class="exam-btn" onclick="v376NewOfficialExam()">＋ Sinh đề THPT mới</button><button class="exam-btn" onclick="closeExamApp();goPage('analytics')">Xem năng lực chi tiết</button></div></div>`}
  function retryWrong(){let x;try{x=JSON.parse(localStorage.getItem(LAST_WRONG_KEY)||'null')}catch(_){x=null}if(!x?.questions?.length){alert('Chưa có câu sai từ lượt thi gần nhất.');return}let cfg={id:`retry-v376-${Date.now().toString(36)}`,mode:'practice-exam',title:'Luyện lại câu sai • Exam Pro',subtitle:`${x.questions.length} câu từ lượt thi gần nhất`,durationMinutes:Math.max(10,x.questions.length*3),questions:x.questions,scoring:'normalized',attemptType:'retry-wrong-v37.6',v376:true,v376Mode:'retry',rules:'Làm lại các câu chưa đúng. Đáp án chỉ hiển thị sau khi nộp để tránh học thuộc máy móc.'};closeExamApp?.();setTimeout(()=>openExamStart(cfg),30)}
