    if(base.move)window.moveExamQuestion=function(step){commitTime();let before=examSession?.current,r=base.move(step);if(examSession?.v376&&examSession.current!==before){examSession.v376.switches++;examSession.v376.enteredAt=Date.now();saveTelemetry()}return r};
